import React, { useState } from 'react';
import DATA from './TrainingData';
import { CenterLayout, CenterLink } from './CenterLayout';
import { Home, Info, Phone, Building, Briefcase, FileText, Globe, Image as ImageIcon, CheckCircle, GraduationCap } from 'lucide-react';

const LINKS: CenterLink[] = [
  { id: 'home', name: 'الرئيسية', icon: Home },
  { 
    id: 'about', 
    name: 'عن المركز', 
    icon: Info,
    children: [
      { id: 'about-brief', name: 'نبذة عن المركز' },
      { id: 'about-strategy', name: 'الخطة الاستراتيجية' },
      { id: 'about-former', name: 'مدراء المركز السابقون' },
      { id: 'about-org-chart', name: 'الهيكل التنظيمي' },
      { id: 'about-council', name: 'مجلس المركز' },
      { id: 'about-staff', name: 'موظفو المركز' },
      { id: 'about-facts', name: 'حقائق و أرقام' },
      { id: 'about-icdl', name: 'مكتب ICDL' }
    ]
  },
  {
    id: 'departments',
    name: 'الدوائر',
    icon: Building,
    children: [
      { id: 'dept-training', name: 'دائرة التدريب' },
      { id: 'dept-courses', name: 'شعبة البرامج و الدورات' },
      { id: 'dept-services', name: 'شعبة خدمات التدريب' },
      { id: 'dept-consulting', name: 'دائرة الاستشارات و التسويق' },
      { id: 'dept-community', name: 'شعبة الاتصال المجتمعي' },
      { id: 'dept-marketing', name: 'شعبة الاستشارات و التسويق' }
    ]
  },
  { id: 'training', name: 'التدريب', icon: GraduationCap },
  { id: 'consultations', name: 'الاستشارات', icon: Briefcase },
  { id: 'partnerships', name: 'الشراكات', icon: Globe },
  { id: 'forms', name: 'النماذج', icon: FileText },
  { id: 'brochures', name: 'نشرات المركز', icon: FileText },
  { id: 'gallery', name: 'معرض الصور', icon: ImageIcon },
  { id: 'news', name: 'الأخبار', icon: FileText },
  { id: 'announcements', name: 'الإعلانات', icon: FileText },
  { id: 'contact', name: 'إتصل بنا', icon: Phone },
];


const HERO = "data:image/jpeg;base64,";
const ROOT = '#/training-center';
const SOURCE = 'https://www.mutah.edu.jo/ar/coc/Home.aspx';
function SourceLink({url = SOURCE}:any) {
  return <p className="mt-10 pt-5 border-t border-slate-200 text-xs text-slate-500 leading-7">المصدر: <a className="underline text-[#0f3057]" href={url} target="_blank" rel="noopener noreferrer">مركز التدريب والاستشارات، جامعة مؤتة</a> · مراجعة المعلومات: 12 سبتمبر 2026</p>;
}
function TrainingPhotos({images,title,single=false}:any) {
  const [limit,setLimit]=useState(12);
  if(!images.length)return null;
  return <section className="mt-8">
    <div className={single?'space-y-6':'grid grid-cols-1 sm:grid-cols-2 gap-6'}>{images.slice(0,limit).map((src:string,i:number)=><figure key={src}>
      <a href={src} target="_blank" rel="noopener noreferrer" aria-label={`${title}، صورة ${i+1}، فتح بالحجم الكامل`}><img src={src} alt={`${title}، صورة ${i+1}`} loading="lazy" className="w-full rounded-lg bg-slate-100" style={{objectFit:'contain',maxHeight:single?'none':'420px'}}/></a>
      <figcaption className="text-xs text-slate-500 mt-2">{title} · {i+1}</figcaption>
    </figure>)}</div>
    {images.length>limit&&<button className="mt-6 px-5 py-3 rounded-lg bg-[#0f3057] text-white" onClick={()=>setLimit(limit+12)}>عرض المزيد من الصور ({images.length-limit})</button>}
  </section>;
}
function ContactDetails() {
  return <div className="space-y-4 mt-6 leading-8 text-[#0f3057]">
    <p>بدالة الجامعة: <a className="underline" href="tel:+96232372380" dir="ltr">+962 3 2372380</a></p>
    <p>التحويلات المنشورة: <strong dir="ltr">4021 · 4177 · 4558</strong></p>
    <p>البريد في صفحة الاتصال: <a className="underline" href="mailto:CSTC@mutah.edu.jo" dir="ltr">CSTC@mutah.edu.jo</a></p>
    <p>البريد في ترويسة الموقع: <a className="underline" href="mailto:coc@mutah.edu.jo" dir="ltr">coc@mutah.edu.jo</a></p>
  </div>;
}
function TrainingPage({tab}:any) {
  const page=DATA[tab];
  if(!page)return <p>اختر صفحة من قائمة المركز.</p>;
  return <article className="bg-white rounded-xl p-5 md:p-9 text-[#0f3057]">
    <h2 className="text-2xl font-bold mb-6">{page.title}</h2>
    <div className="space-y-5 max-w-4xl text-slate-700 leading-9">{page.paragraphs.map((p:string,i:number)=><p key={i}>{p}</p>)}</div>
    {page.sections.map((section:any,i:number)=><section key={i} className="mt-8 max-w-4xl"><h3 className="text-xl font-bold mb-4">{section.title}</h3>
      {section.paragraphs?.map((p:string,j:number)=><p key={j} className="text-slate-700 leading-9">{p}</p>)}
      {section.items&&<ul className="list-disc pr-6 space-y-3 text-slate-700 leading-8">{section.items.map((p:string,j:number)=><li key={j}>{p}</li>)}</ul>}
    </section>)}
    {page.rows.length>0&&<div className="overflow-x-auto mt-7"><table className="w-full text-right text-sm leading-7"><caption className="sr-only">{page.title}</caption>
      <thead><tr className="bg-[#0f3057] text-white">{page.columns.map((c:string)=><th scope="col" key={c} className="p-4">{c}</th>)}</tr></thead>
      <tbody>{page.rows.map((r:string[],i:number)=><tr key={i} className="border-b border-slate-200 even:bg-slate-50">{r.map((v:string,j:number)=><td key={j} className="p-4">{v}</td>)}</tr>)}</tbody>
    </table></div>}
    {tab==='contact'&&<ContactDetails/>}
    {page.docs.length>0&&<section className="mt-8"><h3 className="text-xl font-bold mb-4">الملفات والمرفقات</h3><div className="divide-y divide-slate-200">{page.docs.map(([url,name]:string[])=><a href={url} key={url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 py-4 underline underline-offset-4 break-words"><FileText size={20} className="shrink-0"/><span>{name.replace(/\u200b/g,'')}</span></a>)}</div></section>}
    {['forms','about-facts','dept-services','dept-community','dept-marketing','about-icdl','training'].includes(tab)&&<a className="inline-block mt-7 px-5 py-3 rounded-lg border border-[#0f3057]" href={ROOT+'/contact'}>الاستفسار من المركز</a>}
    {tab==='dept-training'&&<a className="inline-block mt-7 underline" href={ROOT+'/dept-courses'}>استعراض مجالات الدورات والدبلومات</a>}
    <TrainingPhotos images={page.images} title={page.title} single={tab==='about-org-chart'}/>
    <SourceLink url={page.source}/>
  </article>;
}
function TrainingHome() {
  return <div className="space-y-10">
    <section className="bg-white rounded-xl p-6 md:p-9"><p className="text-sm text-slate-500 mb-3">تطوير القدرات وخدمة المجتمع</p><h2 className="text-2xl font-bold text-[#0f3057] mb-5">تدريب واستشارات تستثمر خبرات الجامعة</h2>
      <p className="leading-9 text-slate-700 max-w-4xl">يعمل المركز منذ تأسيسه سنة 2014 على تأهيل الأفراد ومساندة المؤسسات بالدورات والدراسات والاستشارات، مستفيدًا من كفاءات جامعة مؤتة العلمية والفنية والإدارية.</p>
      <div className="flex flex-wrap gap-3 mt-6">{[['dept-courses','الدورات والدبلومات'],['training','الخطط التدريبية'],['consultations','الخدمات الاستشارية'],['contact','تواصل معنا']].map(([id,name])=><a key={id} href={ROOT+'/'+id} className="px-5 py-3 border border-[#0f3057] rounded-lg text-[#0f3057] hover:bg-slate-50">{name}</a>)}</div>
    </section>
    <section className="bg-white rounded-xl p-6 md:p-9"><h2 className="text-2xl font-bold text-[#0f3057] mb-5">مسارات التدريب</h2><ul className="space-y-4 text-slate-700 leading-8 list-disc pr-5"><li>الحاسوب والتقنية والبرمجة والرخصة الدولية ICDL.</li><li>الإدارة والمحاسبة والاتصال واللغات والمهارات الشخصية.</li><li>التدريب المهني والدبلومات المتخصصة.</li></ul><p className="mt-6 text-sm text-slate-500">للمواعيد والرسوم والتسجيل الحالي، يرجى التواصل مع المركز.</p></section>
    <section className="bg-white rounded-xl p-6 md:p-9"><h2 className="text-2xl font-bold text-[#0f3057] mb-4">الأخبار والإعلانات</h2><p className="text-slate-600 leading-8">لا تعرض القوائم الرسمية أخبارًا أو إعلانات حاليًا.</p><div className="flex gap-6 mt-4"><a className="underline text-[#0f3057]" href={ROOT+'/news'}>الأخبار</a><a className="underline text-[#0f3057]" href={ROOT+'/announcements'}>الإعلانات</a><a className="underline text-[#0f3057]" href={ROOT+'/gallery'}>معرض الصور</a></div></section>
    <SourceLink/>
  </div>;
}
export function TrainingCenter() {
  return <CenterLayout centerName="مركز التدريب والاستشارات" links={LINKS} heroDescription="تأهيل الأفراد، وتطوير المؤسسات، وربط المعرفة الجامعية بالتطبيق العملي." heroImage={HERO} heroVariant="photo">
    {(activeItem)=>activeItem==='home'?<TrainingHome/>:<TrainingPage key={activeItem} tab={activeItem}/>}
  </CenterLayout>;
}
